"use strict";(self.webpackChunkhalt_website=self.webpackChunkhalt_website||[]).push([[14284],{8676:e=>{e.exports=JSON.parse('{"tag":{"label":"coat","permalink":"/docs/tags/coat","allTagsPath":"/docs/tags","count":11,"items":[{"id":"Chinchillas/getting-started/grooming-your-chinchilla","title":"Grooming Your Pet Chinchilla","description":"A guide to the unique grooming needs of chinchillas, focusing on the importance of dust baths and how to provide them safely.","permalink":"/docs/Chinchillas/getting-started/grooming-your-chinchilla"},{"id":"Degus/getting-started/grooming-your-degu","title":"Grooming Your Pet Degu","description":"A guide to the grooming needs of pet degus, with a focus on the essential role of dust baths for maintaining their coat and skin health.","permalink":"/docs/Degus/getting-started/grooming-your-degu"},{"id":"Gerbils/getting-started/grooming-your-gerbil","title":"Grooming Your Pet Gerbil","description":"A guide to the minimal grooming needs of pet gerbils, including the role of sand baths, brushing, and nail care.","permalink":"/docs/Gerbils/getting-started/grooming-your-gerbil"},{"id":"guinea-pigs/getting-started/grooming-your-guinea-pig","title":"grooming-your-guinea-pig","description":"Grooming is an essential part of responsible guinea pig care that goes beyond just keeping them looking their best. Regular grooming sessions are an excellent opportunity to bond with your pet and...","permalink":"/docs/guinea-pigs/getting-started/grooming-your-guinea-pig"},{"id":"Chinchillas/breeds-and-genetics/know-your-chinchilla-breeds","title":"Know Your Chinchilla Breeds","description":"An overview of chinchilla species and the wide variety of color mutations found in pet chinchillas.","permalink":"/docs/Chinchillas/breeds-and-genetics/know-your-chinchilla-breeds"},{"id":"Ferrets/breeds-and-genetics/know-your-ferret-colors","title":"Know Your Ferret Colors & Patterns","description":"A guide to ferret coat colors, patterns, and markings recognized by the American Ferret Association.","permalink":"/docs/Ferrets/breeds-and-genetics/know-your-ferret-colors"},{"id":"Gerbils/breeds-and-genetics/know-your-gerbil-breeds","title":"Know Your Gerbil Breeds","description":"An overview of the two species of gerbils commonly kept as pets, and the wide variety of coat colors found in Mongolian gerbils.","permalink":"/docs/Gerbils/breeds-and-genetics/know-your-gerbil-breeds"},{"id":"Mice/breeds-and-genetics/know-your-mouse-breeds","title":"Know Your Mouse Breeds","description":"An overview of the varieties of fancy mice, including coat types, colors, and markings recognized by the American Fancy Rat and Mouse Association.","permalink":"/docs/Mice/breeds-and-genetics/know-your-mouse-breeds"},{"id":"Hamsters/illnesses-and-conditions/seasonal-alopecia","title":"seasonal-alopecia","description":"A guide to seasonal alopecia in hamsters, a harmless, hormone-driven hair loss typically seen in male Syrian hamsters during the winter months.","permalink":"/docs/Hamsters/illnesses-and-conditions/seasonal-alopecia"},{"id":"guinea-pigs/breeds-and-genetics/coat-color-genetics","title":"Understanding Guinea Pig Coat Color Genetics","description":"Guinea pigs are known for their stunning diversity of coat colors and patterns, from solid black to intricate brindles and dalmatians. This variety isn\'t random; it\'s the result of a fascinating and complex world of genetics. Understanding the basics of coat color inheritance is not only interesting for curious owners but is also critical for responsible breeding and rescue advocacy to prevent serious genetic health problems.","permalink":"/docs/guinea-pigs/breeds-and-genetics/coat-color-genetics"},{"id":"guinea-pigs/breeds-and-genetics/hairless-skinny-pigs","title":"What to Know about Hairless or \\"Skinny\\" Pigs","description":"Hairless guinea pigs, most commonly known as \\"Skinny Pigs,\\" are a unique and increasingly popular variety of cavy. Their striking appearance, lacking the typical fluffy coat, makes them stand out, but it also means they have specialized care requirements that potential owners must be prepared to meet. Understanding their unique needs is essential to providing them with a healthy and happy life.","permalink":"/docs/guinea-pigs/breeds-and-genetics/hairless-skinny-pigs"}],"unlisted":false}}')}}]);